import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long x = nextLong();
        HashMap<Long, Long> counts = new HashMap<>(2 * n + 1);
        long answer = 0;
        for (int i = 0; i < n; i++) {
            long r = nextLong() % x;
            answer += counts.getOrDefault((x - r) % x, 0L);  // complementary remainder among earlier items
            counts.merge(r, 1L, Long::sum);
        }
        System.out.println(answer);
    }
}

