import (
	"bufio"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n, x := int(nextInt()), nextInt()
	counts := make(map[int64]int64, n)
	answer := int64(0)
	for i := 0; i < n; i++ {
		r := nextInt() % x
		answer += counts[(x-r)%x] // complementary remainder among earlier items
		counts[r]++
	}
	fmt.Println(answer)
}
